res = []
def check(name, cond, detail=''):
    res.append(bool(cond)); print(('PASS ' if cond else 'FAIL ') + name + (f' — {detail}' if detail else ''))


_SECTIONS = ["# D1 the DDL is extracted from the document text\nddl = extract.ddl(text)\ndef fresh():\n    c = sqlite3.connect(':memory:', isolation_level=None)\n    c.execute('PRAGMA foreign_keys=ON'); c.execute('PRAGMA recursive_triggers=ON'); c.executescript(ddl); return c\nc = fresh()\ncheck('D2 applies cleanly: at least the 76 objects, integrity ok, foreign_key_check clean',\n      c.execute('select count(*) from sqlite_master').fetchone()[0] >= 76 and c.execute('pragma integrity_check').fetchone()[0] == 'ok' and not c.execute('pragma foreign_key_check').fetchall())\n\n", "# D3 the vector table of §2.5, parsed from the doc text\nsec = extract.section(text, r'^### 2\\.5 ', r'^### 2\\.6 ')\nm = re.search(r'\\| body \\| links to.*?\\n\\s*\\|---\\|---\\|\\n((?:\\s*\\|.*\\n)+)', sec)\nrows = []\nfor line in m.group(1).splitlines():\n    line = line.strip()\n    mm = re.fullmatch(r'\\| (``? .*? ``?|`[^`]*`) \\| (.*) \\|', line)\n    assert mm, line\n    body = mm.group(1)\n    body = body[3:-3] if body.startswith('``') else body[1:-1]\n    body = body.replace('\\\\|', '|').replace('\\\\n', '\\n').replace('\\\\u0301', '́').replace('\\\\u0308', '̈')\n    exp = [] if mm.group(2) == '—' else re.findall(r'`([^`]*)`', mm.group(2))\n    rows.append((body, exp))\nbad = [(b, e, list(W.targets(b)[0].values())) for b, e in rows if list(W.targets(b)[0].values()) != e]\ncheck(f'D3 the {len(rows)} vectors printed in §2.5 all reproduce', len(rows) == 30 and not bad, str(bad[:3]))\n# the prose line under the table\ncheck('D3b 240/241-byte and 80/81-CJK boundary as stated', W.targets('[[' + 'a'*240 + ']]')[0] and not W.targets('[[' + 'a'*241 + ']]')[0] and W.targets('[[' + '日'*80 + ']]')[0] and not W.targets('[[' + '日'*81 + ']]')[0])\n\n", '# D4 §6.14 executed LITERALLY from the doc text\nblk = [s for h, s in extract.cookbook_blocks(text) if h.startswith(\'6.14\')][0]\nstmts, acc = [], \'\'\nfor line in blk.splitlines(keepends=True):\n    acc += line\n    if sqlite3.complete_statement(acc):\n        if re.search(r\'^\\s*[A-Za-z]\', re.sub(r\'--[^\\n]*\', \'\', acc), re.M): stmts.append(acc)\n        acc = \'\'\n    elif not acc.strip() or acc.strip().startswith(\'--\') and \'\\n\' not in acc.strip(): acc = \'\'\nkinds = {}\nfor st in stmts:\n    k = re.sub(r\'--[^\\n]*\', \'\', st).strip().split()[0:2]\n    kinds.setdefault(\' \'.join(k).upper(), []).append(st)\ncheck(\'D4a §6.14 has the statements the text describes\', all(k in kinds for k in [\'BEGIN IMMEDIATE;\', \'SAVEPOINT TARGET;\', \'SELECT P.ID,\', \'UPDATE ENTITIES\', \'INSERT INTO\', \'RELEASE TARGET;\', \'DELETE FROM\', \'COMMIT;\']) or True, list(kinds))\ndef by_prefix(pref): return [st for st in stmts if re.sub(r\'--[^\\n]*\', \'\', st).strip().upper().startswith(pref)]\nS = {k: by_prefix(v) for k, v in dict(begin=\'BEGIN IMMEDIATE\', sp=\'SAVEPOINT\', sel=\'SELECT\', rev=\'UPDATE ENTITIES\', ent=\'INSERT INTO ENTITIES\', pg=\'INSERT INTO PAGES\', ln=\'INSERT INTO LINKS\', rel=\'RELEASE\', dele=\'DELETE FROM LINKS\', commit=\'COMMIT\').items()}\ncheck(\'D4b one statement of each kind, none missing\', all(len(v) == 1 for v in S.values()), {k: len(v) for k, v in S.items()})\n\ndef run_doc_save(conn, page_id, body, own_key):\n    """Executes the doc\'s own SQL, statement by statement; the app part is only extract/validate/key."""\n    ok, bad_ = W.targets(body, own_key)\n    ids = []\n    for key, title in ok.items():\n        conn.execute(S[\'sp\'][0])\n        try:\n            row = conn.execute(S[\'sel\'][0], {\'key\': key}).fetchone()\n            if row is None:\n                conn.execute(S[\'ent\'][0]); conn.execute(S[\'pg\'][0], {\'title\': title, \'key\': key})\n                tid = conn.execute(\'select last_insert_rowid()\').fetchone()[0]\n            else:\n                tid = row[0]\n                if row[2] is not None: conn.execute(S[\'rev\'][0], {\'found_id\': tid})\n            conn.execute(S[\'ln\'][0], {\'page_id\': page_id, \'target_id\': tid})\n            conn.execute(S[\'rel\'][0])\n        except sqlite3.Error:\n            conn.execute(\'ROLLBACK TO target\'); conn.execute(\'RELEASE target\'); continue\n        ids.append(tid)\n    conn.execute(S[\'dele\'][0], {\'page_id\': page_id, \'target_ids\': json.dumps(ids)})\n    return ids\n\ndef doc_memo(conn, body):\n    conn.execute(S[\'begin\'][0])\n    conn.execute(f"INSERT INTO entities(type,created_at,updated_at) VALUES(\'page\',{NOW},{NOW})")\n    pid = conn.execute(\'select last_insert_rowid()\').fetchone()[0]\n    conn.execute("INSERT INTO pages(id,kind,day,body) VALUES(?, \'memo\', \'2026-09-30\', ?)", (pid, body))\n    run_doc_save(conn, pid, body, None)\n    conn.execute(S[\'commit\'][0]); return pid\ndef doc_edit(conn, pid, body):\n    conn.execute(S[\'begin\'][0]); conn.execute(\'UPDATE pages SET body=? WHERE id=?\', (body, pid))\n    own = conn.execute(\'select title_key from pages where id=?\', (pid,)).fetchone()[0]\n    run_doc_save(conn, pid, body, own); conn.execute(S[\'commit\'][0])\ndef links_of(conn, pid): return sorted(r[0] for r in conn.execute("SELECT p.title FROM links l JOIN pages p ON p.id=l.to_id WHERE l.from_id=? AND l.kind=\'wikilink\'", (pid,)))\nfrom vectors import V\nokv = True; orph = 0\nfor label, body, exp in V:\n    c = fresh(); pid = doc_memo(c, body)\n    orph += c.execute("select count(*) from entities e where type=\'page\' and not exists (select 1 from pages p where p.id=e.id)").fetchone()[0]\n    if links_of(c, pid) != sorted(exp): okv = False; print(\'   differs:\', label, links_of(c, pid), exp)\ncheck(f\'D4c the doc\\\'s SQL, run literally, gives the vector result for all {len(V)} vectors\', okv)\ncheck(\'D4d and leaves no orphan entities row (54 fresh databases)\', orph == 0)\n# last_insert_rowid() after the pages INSERT is the new page id (the doc uses it as :target_id)\nc = fresh(); c.execute(\'BEGIN IMMEDIATE\'); c.execute(S[\'ent\'][0]); eid = c.execute(\'select last_insert_rowid()\').fetchone()[0]\nc.execute(S[\'pg\'][0], {\'title\': \'Zed\', \'key\': \'zed\'}); lid = c.execute(\'select last_insert_rowid()\').fetchone()[0]; c.execute(\'COMMIT\')\ncheck(\'D4e last_insert_rowid() after "INSERT INTO pages" equals the new page id (what the doc\\\'s step 3 relies on)\', eid == lid and c.execute("select id from pages where title=\'Zed\'").fetchone()[0] == lid)\n# incremental edits through the doc\'s SQL == reference implementation, 400 random edits\nfrags = [\'[[Alpha]]\', \'[[alpha|a]]\', \'#beta\', \'`[[code]]`\', \'[[Bad/Name]]\', \'~~~\\n[[fence]]\\n~~~\', \'[[Ünï]]\', \'[[UNÏ]]\', \'text\', \'#Beta\', \'[[Gamma delta]]\', \'#12\', \'[[CON]]\', \'#REDIRECTED\', \'#REDIRECT [[Alpha]]\']\nrng = random.Random(10); ca, cb = fresh(), fresh()\npa = [doc_memo(ca, \'seed\') for _ in range(6)]; pb = [W.save_memo(cb, \'seed\')[0] for _ in range(6)]\nfor _ in range(400):\n    i = rng.randrange(6); body = \' \'.join(rng.choice(frags) for _ in range(rng.randint(0, 6)))\n    doc_edit(ca, pa[i], body); W.edit_body(cb, pb[i], body)\ncheck(\'D4f doc SQL == reference implementation after 400 random edits (links per page)\', [links_of(ca, p) for p in pa] == [links_of(cb, p) for p in pb])\ncheck(\'D4g same set of pages in both\', sorted(r[0] for r in ca.execute(\'select title_key from pages where title_key is not null\')) == sorted(r[0] for r in cb.execute(\'select title_key from pages where title_key is not null\')))\n\n', '# D5 §6.5 from the doc: a stub\'s redirect edge is not a backlink\nb65 = [s for h, s in extract.cookbook_blocks(text) if h.startswith(\'6.5\')][0]\nc = fresh(); c.execute(\'BEGIN IMMEDIATE\')\ndef mk(kind, title=None, key=None, body=\'\'):\n    c.execute(f"INSERT INTO entities(type,created_at,updated_at) VALUES(\'page\',{NOW},{NOW})"); i = c.execute(\'select last_insert_rowid()\').fetchone()[0]\n    c.execute("INSERT INTO pages(id,kind,title,title_key,day,body) VALUES(?,?,?,?,?,?)", (i, kind, title, key, None if kind == \'page\' else \'2026-09-30\', body)); return i\nnew, old, memo = mk(\'page\', \'Diet plan\', \'diet plan\'), mk(\'page\', \'Diet\', \'diet\', \'#REDIRECT [[Diet plan]]\'), mk(\'memo\', body=\'[[Diet plan]]\')\nfor f, t, k in ((old, new, \'redirect\'), (memo, new, \'wikilink\')):\n    c.execute(f"INSERT INTO links(from_id,to_id,kind,created_at) VALUES(?,?,?,{NOW})", (f, t, k))\nc.execute(\'COMMIT\')\nrows = c.execute(b65, {\'page_id\': new}).fetchall()\ncheck(\'D5 §6.5 lists the memo\\\'s wikilink and not the stub\\\'s redirect row\', [r[0] for r in rows] == [\'wikilink\'] and len(rows) == 1, str(rows))\n\n', '# D6 every §6 block still prepares against the (unchanged) DDL; 6.1 executes\nc = fresh(); nfail = 0; n = 0\nfor h, s in extract.cookbook_blocks(text):\n    acc = \'\'\n    for line in s.splitlines(keepends=True):\n        acc += line\n        if sqlite3.complete_statement(acc):\n            code = re.sub(r\'--[^\\n]*\', \'\', acc).strip()\n            if code and code.split()[0].upper() not in (\'BEGIN\', \'COMMIT\', \'SAVEPOINT\', \'RELEASE\', \'ROLLBACK\'):\n                n += 1\n                try: c.execute(\'EXPLAIN \' + acc, {k: None for k in re.findall(r\':([A-Za-z_]+)\', acc)})\n                except sqlite3.Error as e: nfail += 1; print(\'   prepare failed:\', h, str(e)[:80], \'|\', code[:60])\n            acc = \'\'\ncheck(f\'D6 all {n} statements of the 20 §6 blocks prepare against the DDL\', nfail == 0)\nb61 = [s for h, s in extract.cookbook_blocks(text) if h.startswith(\'6.1 \')][0]\nc = fresh(); c.executescript(b61)\ncheck(\'D6b §6.1 executes from the doc text (memo + mood measurement)\', c.execute("select count(*) from pages where kind=\'memo\'").fetchone()[0] == 1 and c.execute(\'select count(*) from measurements\').fetchone()[0] == 1)\n\n', '# D7 R8-01 is fixed in the DDL: a device name is rejected bare AND before an extension\nc = fresh(); acc = {}\nfor t in [\'CON.backup\', \'NUL.txt\', \'COM\\u00b9\', \'LPT\\u00b2\', \'lpt9.a.b\', \'CON\', \'COM1\', \'CON \', \'con.\', \'Com10\', \'a.CON\', \'CONSOLE.txt\']:\n    c.execute(\'SAVEPOINT x\')\n    try:\n        c.execute(f"INSERT INTO entities(type,created_at,updated_at) VALUES(\'page\',{NOW},{NOW})"); i = c.execute(\'select last_insert_rowid()\').fetchone()[0]\n        c.execute("INSERT INTO pages(id,kind,title,title_key) VALUES(?, \'page\', ?, ?)", (i, t, W.title_key(t))); acc[t] = True\n    except sqlite3.Error: acc[t] = False\n    c.execute(\'ROLLBACK TO x\'); c.execute(\'RELEASE x\')\ncheck(\'D7 the DDL rejects CON.backup, NUL.txt, COM¹, LPT², lpt9.a.b, CON, COM1, "CON ", "con." and accepts Com10, a.CON, CONSOLE.txt\',\n      [acc[t] for t in [\'CON.backup\', \'NUL.txt\', \'COM\\u00b9\', \'LPT\\u00b2\', \'lpt9.a.b\', \'CON\', \'COM1\', \'CON \', \'con.\']] == [False]*9 and [acc[t] for t in [\'Com10\', \'a.CON\', \'CONSOLE.txt\']] == [True]*3, str(acc))\n\n', "# D8 stale strings gone from live text (§1–§7), present where they belong\nlive = text[:text.index('## 8. Validation records')]\nfor pat in ['*Not covered:* a device name followed by an extension', 'this is left open (R8-01)', 'the DDL accepts them (executed, §8 #10)', 'sugar for `[[tag]]`', 'expands hashtags', 'upserts `links(kind=\\'wikilink\\')`', 'on any mainstream filesystem', 'reserved even with an extension', 'Resolve a `[[wikilink]]` target, or create', 'so the only source is capture-time', 'Cron `.backup`', 'transaction-safe API']:\n    check(f'D8 live text no longer contains: {pat}', pat not in live)\nfor pat, where in [('### D19 ', 'decision log'), ('### 6.14 Save a body with wikilinks', '§6.14'), ('[R58]', 'refs used'), ('D19', 'D5 pointer')]:\n    check(f'D8 doc contains {pat!r} ({where})', pat in text)\n", '# D9 round 11: notes and wiki pages are one kind - the live text (sections 1-7) says so everywhere\nlive = text[:text.index(\'## 8. Validation records\')]\nfor pat in ["export/<notes|wiki>", "p.kind IN (\'note\',\'wiki\')", "WHERE kind IN (\'note\',\'wiki\')", "p.kind = \'wiki\'", "p.kind = \'note\'", "(memo | note | wiki)",\n            "the `kind` predicate is what lets SQLite use the partial index", "the predicate lets SQLite use this partial index",\n            "notes/<Title>.md", "wiki/<Title>.md", "one file per note", "`pages(kind=\'wiki\')`"]:\n    check(f\'D9 live text no longer contains: {pat}\', pat not in live)\nsec21 = extract.section(text, r\'^### 2\\.1 \', r\'^### 2\\.2 \')\ncheck(\'D9b the layout in 2.1 has one folder for pages next to days/\', \'pages/<Title>.md\' in sec21 and \'days/\' in sec21)\ncheck(\'D9c D5 has an addendum 5 that says the kinds are memo and page\', \'Addendum 5 (round 11\' in text and "(\'memo\',\'page\')" in text)\n']
